def make_figures(a,r,sensor):
 labels=['Manifest','Response','Trajectory-lite','Attestation','Learned','Frozen contract'];defs=['manifest_pin','response_schema','trajectory_lite','canonical_attestation','learned_relation','toolproof_frozen']
