 cal=[sensor['metrics'][k]['recall'] for k in defs];hold=[r['external_holdout']['defenses'][hold_keys[k]]['recall'] for k in defs]
 x=np.arange(6);w=.34;plt.figure(figsize=(9.3,3.5));plt.bar(x-w/2,cal,w,label='센서 양성대조군',color=ORANGE);plt.bar(x+w/2,hold,w,label='외부-schema hold-out',color=BLUE);plt.xticks(x,labels,rotation=10);plt.ylabel('Recall');plt.ylim(0,1.05);plt.legend(ncol=2);plt.title('그림 1. 센서가 관측하는 공격에서는 0이 아니며, corpus에 따라 탐지 범위가 달라진다')
 for i,v in enumerate(cal):plt.text(i-w/2,v+.02,f'{v:.2f}',ha='center',fontsize=7)
 for i,v in enumerate(hold):plt.text(i+w/2,v+.02,f'{v:.2f}',ha='center',fontsize=7)
 f1=save('coverage.png')
 attacks=sorted(k for k in r['external_holdout']['by_attack'] if k!='none');mat=np.array([[r['external_holdout']['by_attack'][x][d]['recall'] for x in attacks] for d in ['connor_lite_trajectory','learned_effect_relation','toolproof_frozen']]);plt.figure(figsize=(9.2,2.8));plt.imshow(mat,vmin=0,vmax=1,cmap='YlGnBu',aspect='auto');plt.colorbar(label='Recall');plt.yticks(range(3),['Trajectory-lite','Learned relation','Frozen contract']);plt.xticks(range(len(attacks)),[x.replace('_','\n') for x in attacks],fontsize=7)
 for i in range(3):
  for j in range(len(attacks)):plt.text(j,i,f'{mat[i,j]:.2f}',ha='center',va='center',fontsize=8,color='white' if mat[i,j]>.65 else 'black')
 plt.title('그림 2. 공격 계열별 Recall: 집계 F1보다 구조적 실패가 직접 보인다');f2=save('family.png')
 prev=[.5,.1,.01,.001];x=np.arange(4);w=.32;plt.figure(figsize=(9.2,3.0))
