 plt.xticks(x,['1:1','1:9','1:99','1:999']);plt.ylim(0,1.05);plt.ylabel('F1');plt.xlabel('공격:정상');plt.legend();plt.title('그림 3. 저유병률에서는 FPR이 배치 결정을 지배한다');f3=save('prevalence.png')
